import type { LocationInput, TidePrediction } from './types.js';

type NoaaPrediction = {
	t: string;
	v: string;
	type: 'H' | 'L';
};

type NoaaResponse = {
	predictions: NoaaPrediction[];
};

export async function fetchTidePredictions(location: LocationInput, date = new Date()) {
	if (!location.station) {
		throw new Error('NOAA tide predictions require a CO-OPS station id.');
	}

	const begin = date.toISOString().slice(0, 10).replaceAll('-', '');
	const url = new URL('https://api.tidesandcurrents.noaa.gov/api/prod/datagetter');
	url.search = new URLSearchParams({
		product: 'predictions',
		application: 'wxcn',
		begin_date: begin,
		range: '48',
		datum: 'MLLW',
		station: location.station,
		time_zone: 'gmt',
		units: 'english',
		interval: 'hilo',
		format: 'json'
	}).toString();

	const response = await fetch(url);
	if (!response.ok) {
		throw new Error(`NOAA tide lookup failed with ${response.status}`);
	}

	const data = (await response.json()) as NoaaResponse;
	return data.predictions.map((prediction) => ({
		time: prediction.t.replace(' ', 'T') + 'Z',
		height: prediction.v,
		type: prediction.type
	})) satisfies TidePrediction[];
}

export const sampleTides: TidePrediction[] = [
	{ time: '2026-09-06T02:12:00-05:00', height: '1.8', type: 'H' },
	{ time: '2026-09-06T08:28:00-05:00', height: '0.4', type: 'L' },
	{ time: '2026-09-06T14:49:00-05:00', height: '1.5', type: 'H' },
	{ time: '2026-09-06T21:07:00-05:00', height: '0.3', type: 'L' }
];

export const sampleTideTime = Date.parse('2026-09-06T16:30:00Z');
// Illustrative six-minute samples, used only by the labeled coastal example.
export const sampleTideSeries = Array.from({ length: 241 }, (_, i) => {
	const time = Date.parse('2026-09-06T05:00:00Z') + i * 360000;
	return {
		time: new Date(time).toISOString(),
		height: (
			0.95 +
			0.65 *
				Math.cos(((time - Date.parse('2026-09-06T07:12:00Z')) / (12.6 * 3600000)) * 2 * Math.PI)
		).toFixed(3)
	};
});

export type ForecastEntry = { time: number; label: string; summary: string; details: string };
export type ForecastDay = { key: string; label: string; entries: ForecastEntry[] };

/** Group supplied periods in the location's calendar, without inventing missing days. */
export function forecastDays(entries: ForecastEntry[], timeZone: string): ForecastDay[] {
	const key = new Intl.DateTimeFormat('en-CA', {
		timeZone,
		year: 'numeric',
		month: '2-digit',
		day: '2-digit'
	});
	const label = new Intl.DateTimeFormat('en-US', {
		timeZone,
		weekday: 'short',
		month: 'short',
		day: 'numeric'
	});
	const days = new Map<string, ForecastDay>();
	for (const entry of entries
		.filter((e) => Number.isFinite(e.time))
		.toSorted((a, b) => a.time - b.time)) {
		const id = key.format(entry.time);
		if (!days.has(id)) days.set(id, { key: id, label: label.format(entry.time), entries: [] });
		days.get(id)!.entries.push(entry);
	}
	return [...days.values()].slice(0, 7);
}

export type CardSize = 'sm' | 'default' | 'lg';
export type CardDensity = 'compact' | 'comfortable';
export type ForecastType = 'summary' | 'detailed' | 'simple';
export type IconSet = 'hugeicons' | 'phosphor-svelte' | 'lucide' | 'tabler' | 'remix';
export type WeatherUnit = 'fahrenheit' | 'celsius';
export type TideUnit = 'ft' | 'meter';

export type LocationInput = {
	label?: string;
	latitude: number;
	longitude: number;
	station?: string;
	timeZone?: string;
};

export type WeatherPeriod = {
	name: string;
	startTime: string;
	endTime?: string;
	temperature: number;
	temperatureUnit: string;
	windSpeed: string;
	windDirection: string;
	shortForecast: string;
	detailedForecast: string;
	isDaytime: boolean;
};

export type TidePrediction = {
	time: string;
	height: string;
	type: 'H' | 'L';
};

export type MoonForecast = {
	date: string;
	phaseName: string;
	illumination: number;
	age: number;
	nextFullMoon: string;
	nextNewMoon: string;
};

/** Feet above MLLW. Prefer ISO 8601 timestamps with an explicit offset. */
export type TidePoint = { time: string; height: string };
export type TideReading = TidePoint;

/** Current observed conditions; daily extrema use temperatureUnit and the location's calendar day. */
export type CurrentWeather = WeatherPeriod & {
	observedAt: string;
	highToday?: number;
	lowToday?: number;
};

import type { TidePrediction, TideReading, TidePoint } from './types.js';

// Offset-free legacy NOAA values are station wall times; all new API data uses UTC.
export function tideTimestamp(time: string) {
	return Date.parse(/[zZ]|[+-]\d\d:\d\d$/.test(time) ? time : time.replace(' ', 'T') + 'Z');
}
export function tideState(
	predictions: TidePrediction[],
	series: TidePoint[],
	reading: TideReading | null,
	now: number
) {
	const events = predictions
		.filter((p) => Number.isFinite(tideTimestamp(p.time)) && Number.isFinite(Number(p.height)))
		.toSorted((a, b) => tideTimestamp(a.time) - tideTimestamp(b.time));
	const previous = events.filter((p) => tideTimestamp(p.time) <= now).at(-1);
	const next = events.find((p) => tideTimestamp(p.time) > now);
	const points = series
		.map((p) => ({ time: tideTimestamp(p.time), height: Number(p.height) }))
		.filter((p) => Number.isFinite(p.time) && Number.isFinite(p.height))
		.toSorted((a, b) => a.time - b.time);
	const before = points.filter((p) => p.time <= now).at(-1),
		after = points.find((p) => p.time >= now);
	const predicted =
		before && after
			? before.height +
				(after.height - before.height) *
					(after.time === before.time ? 0 : (now - before.time) / (after.time - before.time))
			: null;
	const observed =
		reading &&
		reading.height.trim() &&
		Number.isFinite(Number(reading.height)) &&
		now - tideTimestamp(reading.time) >= 0 &&
		now - tideTimestamp(reading.time) <= 30 * 60000
			? reading
			: null;
	return {
		events,
		previous,
		next,
		points,
		predicted,
		observed,
		level: observed ? Number(observed.height) : predicted
	};
}
